41	/**
42	 * @brief Dump graph to JSON file for debugging
43	 * @param model Model RI handle
44	 * @param metaDir Meta directory path
45	 * @param suffix Filename suffix (e.g., "before" or "after")
46	 * @return aclError status
47	 */
48	aclError DumpMdlJson(aclmdlRI model, const std::string &metaDir, const std::string &suffix) {
49	  if (!sk::logger::FileLogger::Instance().IsEnabled()) {
50	    return ACL_SUCCESS;  // Kernel meta save is disabled, skip
51	  }
52	  std::string jsonPath = metaDir + "/" + suffix + ".json";
53	  aclError ret = aclmdlRIDebugJsonPrint(model, jsonPath.c_str(), 0);
54	  if (ret != ACL_SUCCESS) {
55	    SK_LOGE("Failed to print json file: %s", jsonPath.c_str());
56	    return ACL_ERROR_FAILURE;
57	  }
58	  return ACL_SUCCESS;
59	}
